css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); position: relative; border-radius: 999px; box-shadow: inset 0 2px 5px rgba(15, 23, 42, .28); animation: track-tint calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader span { position: absolute; top: 9%; width: 44%; height: 82%; border-radius: 50%; background: #f8fafc; box-shadow: 0 2px 5px rgba(15, 23, 42, .3); animation: knob-slide calc(var(--loader-speed) * 2.2) cubic-bezier(.45, 1.5, .5, 1) infinite; }
@keyframes track-tint { 0%, 20% { background: color-mix(in srgb, #000 14%, var(--accent-2)); } 46%, 70% { background: var(--accent); } 96%, 100% { background: color-mix(in srgb, #000 14%, var(--accent-2)); } }
@keyframes knob-slide { 0%, 20% { left: 3%; } 46%, 70% { left: 53%; } 96%, 100% { left: 3%; } }
